import { useEffect, useState } from "react";

/**
 * IAB Tech Lab taxonomies, as code → tier path, for the package form's
 * pickers. Generated by scripts/build-taxonomies.mjs from the copies the
 * seller agent vendors; both are CC BY 3.0 (README.md carries the credit).
 *
 * Loaded on demand: the two lists are ~30 kB gzipped together, and only a
 * package form ever needs them, so they stay out of the initial bundle.
 */
export type TaxonomyId = "content-3.1" | "audience-1.1";

export type Taxonomy = {
  readonly title: string;
  readonly attribution: string;
  /** Code → tier path, in the file's order. */
  readonly names: ReadonlyMap<string, string>;
};

type File = { title: string; attribution: string; entries: [string, string][] };

const LOADERS: Record<TaxonomyId, () => Promise<{ default: unknown }>> = {
  "content-3.1": () => import("./content-3.1.json"),
  "audience-1.1": () => import("./audience-1.1.json"),
};

// One load per taxonomy per page: every picker that asks shares it.
const loaded = new Map<TaxonomyId, Promise<Taxonomy>>();

function load(id: TaxonomyId): Promise<Taxonomy> {
  let pending = loaded.get(id);
  if (!pending) {
    pending = LOADERS[id]().then(({ default: raw }) => {
      const file = raw as File;
      return { title: file.title, attribution: file.attribution, names: new Map(file.entries) };
    });
    // A failed chunk load (offline, a deploy swapped the chunk) must not be
    // cached as the answer; the next picker to open tries again.
    pending.catch(() => loaded.delete(id));
    loaded.set(id, pending);
  }
  return pending;
}

/**
 * The taxonomy, once loaded; undefined while loading, when it failed, or when
 * `id` is undefined (the caller does not need one right now). A picker
 * without its list still takes typed codes, so a failure only costs the names.
 */
export function useTaxonomy(id: TaxonomyId | undefined): Taxonomy | undefined {
  const [state, setState] = useState<{ id: TaxonomyId; taxonomy: Taxonomy } | undefined>();
  useEffect(() => {
    if (!id) return;
    let live = true;
    load(id).then(
      (taxonomy) => {
        if (live) setState({ id, taxonomy });
      },
      () => undefined,
    );
    return () => {
      live = false;
    };
  }, [id]);
  return state && state.id === id ? state.taxonomy : undefined;
}
